def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    total_alive = 1 + len(alive_opponents)
    units = int(supply // WATER_REQ)
    scarcity = total_alive - units

    prev_bids = []
    desperate_opps = 0
    rich_opps = 0
    for opp in alive_opponents:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_opps += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 4:
            rich_opps += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    if hp <= 2 or no_water >= 1:
        base = DAILY_SALARY * 0.92
    elif scarcity <= 0:
        base = DAILY_SALARY * 0.28
    elif scarcity == 1:
        base = DAILY_SALARY * 0.48
    else:
        base = DAILY_SALARY * 0.68

    pressure = 0
    pressure += min(12, max(0, scarcity) * 4)
    pressure += min(10, desperate_opps * 3)
    pressure += min(6, rich_opps * 2)

    if highest_prev > 0:
        target = max(base + pressure, avg_prev + 2, highest_prev + 1)
    else:
        target = base + pressure

    if hp >= 4 and no_water == 0 and scarcity <= 0:
        target = min(target, DAILY_SALARY * 0.35)

    if budget < target:
        if hp <= 2 or no_water >= 1:
            return budget
        target = max(0, budget * 0.75)

    target = min(target, budget)
    if target < 0:
        target = 0
    return target

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], 1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    bid_amount = DAILY_SALARY * 0.5 # Default moderate bid

    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)
        avg_yesterday_bid = sum(yesterday_bids) / len(yesterday_bids)

        if my_status['hp'] <= 3:
            bid_amount = max(max_yesterday_bid + 10, DAILY_SALARY * 0.95)
        elif my_status['hp'] <= 6:
            bid_amount = max(max_yesterday_bid + 5, DAILY_SALARY * 0.75)
        else:
            if day_context['day'] <= 3:
                bid_amount = max(avg_yesterday_bid + 1, DAILY_SALARY * 0.4)
            else:
                bid_amount = max(max_yesterday_bid + 1, DAILY_SALARY * 0.6)
    else:
        if my_status['hp'] <= 3:
            bid_amount = DAILY_SALARY * 0.9
        elif my_status['hp'] <= 6:
            bid_amount = DAILY_SALARY * 0.7
        else:
            bid_amount = DAILY_SALARY * 0.5

    final_bid = min(my_status['budget'], bid_amount)
    final_bid = max(1, final_bid)

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    hp = my_status['hp']
    no_water = my_status['no_water_days']
    day = int(day_context['day']) if hasattr(day_context['day'], '__int__') else day_context['day']
    # urgency based on health and remaining days
    base_bid = DAILY_SALARY * 0.4
    if day >= 8:
        base_bid = DAILY_SALARY * 0.7
    if no_water >= 2 or hp <= 2:
        base_bid = DAILY_SALARY * 0.9
    elif no_water == 1 or hp <= 4:
        base_bid = max(base_bid, DAILY_SALARY * 0.6)
    return min(my_status['budget'], base_bid)
